//nanopb protobuf encoding for `TelemetryPayload` (schema: proto/telemetry.proto).

//The struct and C functions are generated by build.rs. All unsafe FFI code
//for them is confined to this module.

#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]
mod ffi {
    include!(concat!(env!("OUT_DIR"), "/telemetry_bindings.rs"));
}

pub use ffi::TelemetryPayload;

/// Worst-case encoded size, computed by the nanopb generator.
const MAX_ENCODED_SIZE: usize = ffi::TelemetryPayload_size as usize;

/// Encode a payload to protobuf bytes. Returns `None` if nanopb reports an error.
pub fn encode(msg: &TelemetryPayload) -> Option<Vec<u8>> {
    let mut buf = vec![0u8; MAX_ENCODED_SIZE];
    let mut written: usize = 0;
    // SAFETY: `msg` is a valid TelemetryPayload, `buf` is writable for `buf.len()`
    // bytes, and `written` is a valid out-pointer. None are retained after the call.
    let ok = unsafe { ffi::telemetry_encode(msg, buf.as_mut_ptr(), buf.len(), &mut written) };
    if !ok || written > buf.len() {
        return None;
    }
    buf.truncate(written);
    Some(buf)
}

/// Decode protobuf bytes into a payload. Returns `None` on malformed input.
pub fn decode(bytes: &[u8]) -> Option<TelemetryPayload> {
    let mut out = TelemetryPayload::default();
    // SAFETY: `bytes` is readable for `bytes.len()` bytes and `out` is a valid,
    // exclusively borrowed TelemetryPayload. None are retained after the call.
    let ok = unsafe { ffi::telemetry_decode(bytes.as_ptr(), bytes.len(), &mut out) };
    ok.then_some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> TelemetryPayload {
        TelemetryPayload {
            sync_word: 0xDEAD_BEEF,
            flight_mode: 3,
            pressure: 101_325.5,
            temp: 21.75,
            altitude: 1234.5,
            latitude: 42.444_6,
            longitude: -76.501_9,
            num_satellites: 12,
            gps_time: 45_296_123.0,
            mag_x: 0.11,
            mag_y: -0.22,
            mag_z: 0.33,
            accel_x: 1.5,
            accel_y: -2.5,
            accel_z: 9.81,
            gyro_x: -0.01,
            gyro_y: 0.02,
            gyro_z: -0.03,
            pt3: 512.0,
            pt4: 498.25,
            rtd: 18.5,
            sv_2_open: true,
            mav_open: true,
            ms_since_boot_cfc: 987_654,
            ssa_drogue_deployed: 1,
            ssa_main_deployed: 1,
            cmd_n1: 1,
            cmd_n2: 2,
            cmd_n3: 3,
            cmd_n4: 4,
            cmd_a1: 5,
            cmd_a2: 6,
            cmd_a3: 7,
            airbrake_deployment: 0.42,
            predicted_apogee: 3048.0,
            h_acc: 1500,
            v_acc: 2500,
            vel_n: 1.25,
            vel_e: -3.5,
            vel_d: -150.75,
            g_speed: 3.75,
            s_acc: 120,
            head_acc: 450,
            fix_type: 3,
            head_mot: -1_234_567,
            blims_brakeline_diff: -0.5,
            blims_phase_id: -1,
            blims_pid_p: 0.8,
            blims_pid_i: 0.05,
            blims_bearing: 270.5,
            blims_upwind_lat: 42.45,
            blims_upwind_lon: -76.49,
            blims_downwind_lat: 42.43,
            blims_downwind_lon: -76.51,
            blims_wind_from_deg: 225.0,
            pt_1_pressure: 750.5,
            pt_2_pressure: 680.25,
            ball_valve_open: true,
            sv_1_open: true,
            load_cell: 55.5,
            ignition: true,
            qd_state: -1,
            ms_since_boot_fill: u64::MAX - 1,
            availability_version: 1,
            configured_devices_mask: 4095,
            valid_readings_mask: 7,
        }
    }

    #[test]
    fn round_trip() {
        let original = sample();
        let bytes = encode(&original).expect("encode failed");
        assert!(bytes.len() <= MAX_ENCODED_SIZE);
        let decoded = decode(&bytes).expect("decode failed");
        // PartialEq is derived by bindgen and compares every field.
        assert_eq!(original, decoded);
        assert_eq!(decoded.sync_word, 0xDEAD_BEEF);
        assert!(decoded.sv_2_open && decoded.mav_open && decoded.ball_valve_open);
        assert!(decoded.sv_1_open && decoded.ignition);
        assert_eq!(decoded.ms_since_boot_fill, u64::MAX - 1);
        assert_eq!(decoded.head_mot, -1_234_567);
        assert_eq!(decoded.blims_phase_id, -1);
        assert_eq!(decoded.qd_state, -1);
    }

    #[test]
    fn decode_rejects_garbage() {
        assert!(decode(&[0xFF, 0xFF, 0xFF]).is_none());
    }
}
